"""Orchestrates one analysis: parse -> static checks -> LLM review -> report."""
from __future__ import annotations

import asyncio
import re
import time
from dataclasses import asdict

from .llm import LLMError, LLMProvider
from .parser import ContractInfo, FunctionInfo, ParsedSource, parse_sources, pick_main_contract
from .static_checks import (
    SEVERITY_ORDER,
    Finding,
    access_modifiers,
    external_calls,
    is_access_controlled,
    run_static_checks,
    state_writes,
)

DISCLAIMER = (
    "This report is generated by an automated review assistant (rule-based checks plus an AI model). "
    "It is meant to speed up review, not replace a professional security audit. Findings can be "
    "incomplete or wrong; verify every item before relying on it."
)
CATEGORIES = {"reentrancy", "access-control", "owner-powers", "unchecked-call", "tx-origin", "logic", "other"}
DEPENDENCY_PATH_RE = re.compile(r"(@openzeppelin|node_modules|^lib/|/lib/|solmate|solady|@uniswap|@chainlink)", re.I)
MAX_FN_LINES_FOR_LLM = 150

SYSTEM_PROMPT = """You are a senior smart-contract security reviewer helping a human reviewer move faster.
You are an assistant, not an auditor: be precise, conservative and plain-spoken.
Rules:
- Only cite line numbers that appear in the numbered code you were given.
- Never invent functions, variables or behaviour that is not in the code.
- Explain for a technical reader who may not know Solidity well; avoid jargon or define it briefly.
- If something is ambiguous, say so instead of guessing.
- Reply with a single JSON object and nothing else."""


# --------------------------------------------------------------------------- selection

def _is_dependency(c: ContractInfo) -> bool:
    return bool(DEPENDENCY_PATH_RE.search(c.file))


def select_contracts(parsed: ParsedSource, main: ContractInfo, source_type: str) -> list[ContractInfo]:
    lineage = [c for c in parsed.lineage(main.name) if c.kind != "interface"]
    if main.kind != "library":
        lineage = [c for c in lineage if c.kind != "library"]
    selected = list(lineage)
    if source_type == "code":
        for c in parsed.contracts:
            if c not in selected and c.kind in {"contract", "abstract"} and not _is_dependency(c):
                selected.append(c)
    return selected


def _priority(fn: FunctionInfo, main: ContractInfo, flagged: set[str], dep: bool) -> tuple:
    return (
        dep,
        fn.contract != main.name,
        fn.id not in flagged,
        not (fn.is_externally_callable and fn.is_state_changing),
        not fn.is_externally_callable,
        fn.start_line,
    )


# --------------------------------------------------------------------------- static facts

def who_can_call(fn: FunctionInfo, svars: set[str] | None = None) -> str:
    if fn.kind == "constructor":
        return "Deployer (runs once at deployment)"
    if fn.kind == "modifier":
        return "Used by other functions"
    if fn.visibility in {"internal", "private"}:
        return "Internal only"
    mods = access_modifiers(fn)
    if mods:
        return "Restricted: " + ", ".join(mods)
    if is_access_controlled(fn, svars):
        return "Restricted (sender check in code)"
    return "Anyone"


def static_facts(parsed: ParsedSource, fn: FunctionInfo) -> dict:
    svars = parsed.state_var_names(fn.contract)
    writes = sorted({w[0] for w in state_writes(fn, svars)})
    calls = sorted({c[0] for c in external_calls(fn)})
    events = sorted(set(re.findall(r"\bemit\s+([A-Za-z_]\w*)", fn.masked)))
    return {"writes": writes, "calls": calls, "events": events}


CALL_LABELS = {
    "value-call": "sends ETH via low-level call",
    "call": "makes a low-level call",
    "delegatecall": "delegatecalls another contract",
    "token": "calls a token contract",
    "transfer": "sends ETH (transfer)",
    "send": "sends ETH (send)",
}


def heuristic_summary(fn: FunctionInfo, facts: dict) -> str:
    kind = {"constructor": "Constructor", "modifier": "Modifier", "fallback": "Fallback", "receive": "Receive"}.get(
        fn.kind, "Function"
    )
    parts = [f"{kind} `{fn.name}` ({fn.visibility}{', payable' if fn.mutability == 'payable' else ''}"
             f"{', read-only' if not fn.is_state_changing else ''})."]
    if facts["writes"]:
        parts.append("Updates " + ", ".join(f"`{w}`" for w in facts["writes"][:5]) + ".")
    if facts["calls"]:
        parts.append("It " + "; ".join(CALL_LABELS[c] for c in facts["calls"]) + ".")
    if facts["events"]:
        parts.append("Emits " + ", ".join(facts["events"][:4]) + ".")
    return " ".join(parts)


def detect_contract_type(fns: list[FunctionInfo], contracts: list[ContractInfo]) -> str:
    names = {f.name for f in fns}
    bases = {b for c in contracts for b in c.bases} | {c.name for c in contracts}
    if {"ownerOf", "safeTransferFrom"} <= names or any("ERC721" in b for b in bases):
        return "NFT (ERC-721)"
    if any("ERC1155" in b for b in bases) or "safeBatchTransferFrom" in names:
        return "Multi-token (ERC-1155)"
    if {"swap", "mint", "burn", "getReserves"} <= names:
        return "AMM liquidity pool"
    if {"transfer", "approve", "balanceOf"} <= names or any("ERC20" in b for b in bases):
        return "Fungible token (ERC-20)"
    if any(re.search(r"proxy", b, re.I) for b in bases):
        return "Proxy"
    if names & {"deposit", "withdraw"}:
        return "Vault / funds-holding contract"
    return "Smart contract"


def static_roles(parsed: ParsedSource, fns: list[FunctionInfo]) -> list[dict]:
    roles: dict[str, list[str]] = {}
    for fn in fns:
        if not (fn.is_externally_callable and fn.is_state_changing):
            continue
        mods = access_modifiers(fn)
        if mods:
            for m in mods:
                roles.setdefault(m, []).append(fn.name)
        elif is_access_controlled(fn, parsed.state_var_names(fn.contract)):
            roles.setdefault("sender check in code", []).append(fn.name)
    out = []
    for mod, powers in roles.items():
        label = re.sub(r"^only", "", mod) or mod
        label = {"Role": "Role holder (AccessControl)", "auth": "Authorized (wards)",
                 "sender check in code": "Restricted caller (checked in code)"}.get(label, label[:1].upper() + label[1:])
        out.append({"role": label, "via": mod, "description": "", "powers": sorted(set(powers))})
    return out


# --------------------------------------------------------------------------- LLM prompts

def _numbered(fn: FunctionInfo) -> str:
    lines = fn.code.split("\n")
    clipped = lines[:MAX_FN_LINES_FOR_LLM]
    body = "\n".join(f"{fn.start_line + i:>5}| {line}" for i, line in enumerate(clipped))
    if len(lines) > len(clipped):
        body += f"\n  ... ({len(lines) - len(clipped)} more lines omitted)"
    return body


def _contract_context(parsed: ParsedSource, contract: ContractInfo) -> str:
    lineage = parsed.lineage(contract.name)
    svars = [f"{v.type} {v.name}" + (" (constant)" if v.constant else "") for c in lineage for v in c.state_vars][:40]
    modifiers = [m for c in lineage for m in c.functions if m.kind == "modifier"]
    mod_code = "\n\n".join(_numbered(m) for m in modifiers)[:2500]
    return (
        f"Contract `{contract.name}` ({contract.kind}), inherits: {', '.join(contract.bases) or 'nothing'}.\n"
        f"State variables: {', '.join(svars) or 'none found'}\n"
        f"Modifiers defined:\n{mod_code or 'none'}"
    )


def build_batch_prompt(parsed: ParsedSource, contract: ContractInfo, fns: list[FunctionInfo], findings: list[Finding]) -> str:
    by_fn: dict[str, list[Finding]] = {}
    for f in findings:
        by_fn.setdefault(f.function_id, []).append(f)
    blocks = []
    for fn in fns:
        hits = by_fn.get(fn.id, [])
        hit_txt = "; ".join(f"[{h.id}] {h.severity}: {h.title} (lines {h.lines[0]}-{h.lines[1]})" for h in hits) or "none"
        blocks.append(
            f"### id: {fn.id}\nkind: {fn.kind}, visibility: {fn.visibility}, mutability: {fn.mutability}, "
            f"modifiers: {', '.join(fn.modifiers) or 'none'}\nstatic findings: {hit_txt}\n{_numbered(fn)}"
        )
    return f"""Context:
{_contract_context(parsed, contract)}

Review each function below. Static rules already flagged some issues; triage those instead of repeating them.

{chr(10).join(blocks)}

Return JSON exactly in this shape:
{{
  "functions": [
    {{
      "id": "<id as given>",
      "summary": "<1-2 plain-English sentences: what it does and why it matters>",
      "who_can_call": "<e.g. Anyone | Owner only | MINTER_ROLE | Internal only>",
      "risks": [
        {{
          "title": "<short>",
          "severity": "critical|high|medium|low|info",
          "category": "reentrancy|access-control|owner-powers|unchecked-call|logic|other",
          "lines": [<start>, <end>],
          "explanation": "<why this is risky, 1-3 sentences>",
          "fix": "<concrete suggested fix>"
        }}
      ]
    }}
  ],
  "static_triage": [
    {{"finding_id": "<S#>", "verdict": "confirmed|likely_false_positive|needs_review", "reason": "<1 sentence>"}}
  ]
}}
Only add risks NOT already covered by the static findings. Max 3 risks per function; use [] when there is nothing notable. Prefer fewer, well-founded risks over speculative ones."""


def build_synthesis_prompt(meta: dict, contracts: list[ContractInfo], functions: list[dict], findings: list[dict], roles: list[dict]) -> str:
    fn_lines = "\n".join(
        f"- {f['id']} [{f['who_can_call']}]: {f['summary'][:220]}" for f in functions if f["kind"] != "modifier"
    )[:9000]
    fd_lines = "\n".join(
        f"- {f['id']} {f['severity']} ({f['source']}{', ' + f['triage']['verdict'] if f.get('triage') else ''}): {f['title']} in {f['function_name']}"
        for f in findings
    )[:5000]
    role_lines = "\n".join(f"- {r['role']} via {r['via']}: {', '.join(r['powers'])}" for r in roles) or "none detected"
    return f"""Contract: {meta['name']} ({meta.get('contract_type')}). Inheritance chain: {', '.join(c.name for c in contracts)}.
{('Notes: ' + ' '.join(meta['notes'])) if meta.get('notes') else ''}

Function summaries:
{fn_lines}

Findings:
{fd_lines or 'none'}

Privileged roles detected statically:
{role_lines}

Write the top of a review report. Return JSON:
{{
  "overview": "<3-5 plain-English sentences: what this contract does, who interacts with it, how value flows>",
  "contract_type": "<e.g. ERC-20 token with fees>",
  "roles": [{{"role": "<name>", "description": "<who this is, 1 sentence>", "powers": ["<plain-English power>", "..."]}}],
  "key_function_ids": ["<up to 8 function ids that matter most to users or reviewers>"],
  "risk_summary": "<2-3 sentences on the most important risks, or say none stood out>",
  "top_fixes": ["<up to 5 prioritized, concrete recommendations>"]
}}"""


# --------------------------------------------------------------------------- analysis

def _chunks(fns: list[FunctionInfo], max_chars: int = 12000, max_fns: int = 8) -> list[list[FunctionInfo]]:
    out, cur, size = [], [], 0
    for fn in fns:
        n = len(fn.code)
        if cur and (size + n > max_chars or len(cur) >= max_fns):
            out.append(cur)
            cur, size = [], 0
        cur.append(fn)
        size += n
    if cur:
        out.append(cur)
    return out


def _valid_lines(lines, fn: FunctionInfo) -> tuple[list[int], bool]:
    try:
        a, b = int(lines[0]), int(lines[-1])
    except (TypeError, ValueError, IndexError):
        return [fn.start_line, fn.end_line], False
    a, b = min(a, b), max(a, b)
    if a >= fn.start_line and b <= fn.end_line:
        return [a, b], True
    if b < fn.start_line or a > fn.end_line:
        return [fn.start_line, fn.end_line], False
    return [max(a, fn.start_line), min(b, fn.end_line)], False


async def analyze(
    files: list[tuple[str, str]],
    *,
    provider: LLMProvider | None,
    source_type: str = "code",
    main_name: str | None = None,
    meta_extra: dict | None = None,
    max_llm_functions: int = 40,
    concurrency: int = 4,
) -> dict:
    t0 = time.perf_counter()
    parsed = parse_sources(files)
    main = pick_main_contract(parsed, main_name)
    if main is None:
        raise ValueError("No contract, library or interface definition found in the source.")

    contracts = select_contracts(parsed, main, source_type)
    fns = [f for c in contracts for f in c.functions if f.has_body]
    findings = run_static_checks(parsed, fns)
    flagged = {f.function_id for f in findings}
    dep_contracts = {c.name for c in contracts if _is_dependency(c)}
    notes: list[str] = list((meta_extra or {}).get("notes", []))

    facts = {fn.id: static_facts(parsed, fn) for fn in fns}
    fn_report: dict[str, dict] = {}
    for fn in fns:
        fn_report[fn.id] = {
            "id": fn.id,
            "contract": fn.contract,
            "name": fn.name,
            "kind": fn.kind,
            "visibility": fn.visibility,
            "mutability": fn.mutability,
            "modifiers": fn.modifiers,
            "file": fn.file,
            "start_line": fn.start_line,
            "end_line": fn.end_line,
            "signature": fn.signature,
            "who_can_call": who_can_call(fn, parsed.state_var_names(fn.contract)),
            "summary": heuristic_summary(fn, facts[fn.id]),
            "writes": facts[fn.id]["writes"],
            "calls": facts[fn.id]["calls"],
            "is_dependency": fn.contract in dep_contracts,
            "ai_analyzed": False,
            "is_key": False,
        }

    ai_findings: list[Finding] = []
    synthesis: dict = {}
    if provider is not None:
        candidates = [f for f in fns if f.kind != "modifier"]
        candidates.sort(key=lambda f: _priority(f, main, flagged, f.contract in dep_contracts))
        to_ai = candidates[:max_llm_functions]
        if len(candidates) > len(to_ai):
            notes.append(
                f"AI review covered the {len(to_ai)} most relevant of {len(candidates)} functions; "
                "the rest have static checks and rule-based summaries only."
            )
        await _run_function_batches(parsed, to_ai, findings, fn_report, ai_findings, provider, concurrency, notes)

    all_findings = findings + ai_findings
    contract_type = detect_contract_type(fns, contracts)
    roles = static_roles(parsed, fns)
    findings_out = [_finding_dict(f) for f in all_findings]
    fn_list = sorted(fn_report.values(), key=lambda f: (f["is_dependency"], f["contract"] != main.name, f["file"], f["start_line"]))

    meta = {
        "name": main.name,
        "contract_type": contract_type,
        "source_type": source_type,
        "notes": notes,
        **{k: v for k, v in (meta_extra or {}).items() if k != "notes"},
    }

    if provider is not None:
        try:
            synthesis = await provider.complete_json(
                SYSTEM_PROMPT, build_synthesis_prompt(meta, contracts, fn_list, findings_out, roles), 2500
            )
        except LLMError as exc:
            notes.append(f"AI overview unavailable ({exc}); showing rule-based overview.")
            synthesis = {}

    report = _assemble(main, contracts, parsed, fn_list, fn_report, findings_out, roles, synthesis, meta, provider)
    report["meta"]["duration_ms"] = int((time.perf_counter() - t0) * 1000)
    return report


async def _run_function_batches(parsed, to_ai, findings, fn_report, ai_findings, provider, concurrency, notes):
    sem = asyncio.Semaphore(max(1, concurrency))
    by_contract: dict[str, list[FunctionInfo]] = {}
    for fn in to_ai:
        by_contract.setdefault(fn.contract, []).append(fn)
    jobs = []
    for cname, cfns in by_contract.items():
        contract = parsed.contract(cname)
        for chunk in _chunks(cfns):
            chunk_ids = {f.id for f in chunk}
            chunk_findings = [f for f in findings if f.function_id in chunk_ids]
            jobs.append((chunk, chunk_findings, build_batch_prompt(parsed, contract, chunk, chunk_findings)))

    async def run(job):
        async with sem:
            return await provider.complete_json(SYSTEM_PROMPT, job[2], 4000)

    results = await asyncio.gather(*(run(j) for j in jobs), return_exceptions=True)
    failed = 0
    first_error = ""
    fn_index = {f.id: f for f in to_ai}
    finding_index = {f.id: f for f in findings}
    counter = 0
    for (chunk, chunk_findings, _), res in zip(jobs, results):
        if isinstance(res, Exception):
            failed += len(chunk)
            first_error = first_error or str(res)[:200]
            continue
        valid_ids = {f.id for f in chunk_findings}
        for item in res.get("static_triage", []) or []:
            fid = str(item.get("finding_id", ""))
            verdict = item.get("verdict")
            if fid in valid_ids and verdict in {"confirmed", "likely_false_positive", "needs_review"}:
                finding_index[fid].triage = {"verdict": verdict, "reason": str(item.get("reason", ""))[:400]}
        for item in res.get("functions", []) or []:
            fid = item.get("id")
            fn = fn_index.get(fid)
            if fn is None or fid not in {f.id for f in chunk}:
                continue  # ignore hallucinated ids
            rep = fn_report[fid]
            if item.get("summary"):
                rep["summary"] = str(item["summary"])[:600]
            if item.get("who_can_call") and rep["who_can_call"] != "Internal only":
                rep["who_can_call_ai"] = str(item["who_can_call"])[:120]
            rep["ai_analyzed"] = True
            static_cats = {f.category for f in findings if f.function_id == fid}
            for risk in (item.get("risks") or [])[:3]:
                sev = str(risk.get("severity", "")).lower()
                cat = str(risk.get("category", "other")).lower()
                if sev not in SEVERITY_ORDER:
                    continue
                cat = cat if cat in CATEGORIES else "other"
                if cat in static_cats and cat != "logic":
                    continue  # already covered by a deterministic rule
                lines, exact = _valid_lines(risk.get("lines"), fn)
                counter += 1
                ai_findings.append(
                    Finding(
                        id=f"A{counter}",
                        title=str(risk.get("title", "Potential issue"))[:160],
                        severity=sev,
                        category=cat,
                        function_id=fn.id,
                        function_name=fn.name,
                        contract=fn.contract,
                        file=fn.file,
                        lines=lines,
                        explanation=str(risk.get("explanation", ""))[:1200],
                        fix=str(risk.get("fix", ""))[:800],
                        source="ai",
                        extra={} if exact else {"line_check": "AI cited lines outside this function; showing the whole function."},
                    )
                )
    if failed:
        notes.append(f"AI review failed for {failed} function(s); they show static results only. Reason: {first_error}")


def _finding_dict(f: Finding) -> dict:
    d = asdict(f)
    d["line_note"] = d.pop("extra", {}).get("line_check")
    return d


def _assemble(main, contracts, parsed, fn_list, fn_report, findings_out, roles, synthesis, meta, provider) -> dict:
    sev_rank = {s: i for i, s in enumerate(SEVERITY_ORDER)}
    findings_out.sort(key=lambda f: (
        bool(f.get("triage")) and f["triage"]["verdict"] == "likely_false_positive",
        sev_rank[f["severity"]],
        f["file"],
        f["lines"][0],
    ))
    active = [f for f in findings_out if not (f.get("triage") and f["triage"]["verdict"] == "likely_false_positive")]
    counts = {s: sum(1 for f in active if f["severity"] == s) for s in SEVERITY_ORDER}
    counts["dismissed"] = len(findings_out) - len(active)

    worst = next((s for s in SEVERITY_ORDER[:3] if counts[s]), None)
    overall = worst or ("low" if counts["low"] or counts["info"] else "low")

    # key functions
    valid_ids = set(fn_report)
    key_ids = [i for i in synthesis.get("key_function_ids", []) if i in valid_ids][:8]
    if not key_ids:
        flagged = {f["function_id"] for f in active}
        pool = [f for f in fn_list
                if f["contract"] == main.name and f["kind"] in {"function", "fallback", "receive"}
                and f["visibility"] in {"public", "external"} and f["mutability"] not in {"view", "pure"}]
        pool.sort(key=lambda f: (f["id"] not in flagged, f["who_can_call"] == "Anyone", f["start_line"]))
        key_ids = [f["id"] for f in pool][:8]
    for i in key_ids:
        fn_report[i]["is_key"] = True
    risk_counts: dict[str, int] = {}
    for f in active:
        risk_counts[f["function_id"]] = risk_counts.get(f["function_id"], 0) + 1
    for f in fn_list:
        f["risk_count"] = risk_counts.get(f["id"], 0)

    # roles: prefer AI descriptions, keep static "via" mapping
    ai_roles = synthesis.get("roles") if isinstance(synthesis.get("roles"), list) else None
    if ai_roles:
        roles_out = [{"role": str(r.get("role", ""))[:80], "description": str(r.get("description", ""))[:300],
                      "powers": [str(p)[:200] for p in (r.get("powers") or [])][:10]} for r in ai_roles if r.get("role")]
    else:
        roles_out = [{
            "role": r["role"],
            "description": "Callers that pass an explicit `msg.sender` check inside the function." if r["via"] == "sender check in code"
            else f"Accounts allowed by the `{r['via']}` modifier.",
            "powers": [f"Call `{p}`" for p in r["powers"]],
        } for r in roles]

    ext = [f for f in fn_list if f["visibility"] in {"public", "external"} and f["kind"] != "constructor"]
    state_changing = [f for f in ext if f["mutability"] not in {"view", "pure"}]
    overview_txt = synthesis.get("overview") or (
        f"`{main.name}` looks like a {meta['contract_type'].lower()}. It defines {len(fn_list)} functions "
        f"({len(ext)} callable from outside, {len(state_changing)} of which change state)"
        + (f" and inherits from {', '.join(main.bases)}" if main.bases else "")
        + ". This overview is rule-based because the AI layer is off."
    )
    fixes = [str(x)[:400] for x in synthesis.get("top_fixes", []) if x][:5]
    if not fixes:
        seen = []
        for f in active:
            if f["fix"] not in seen:
                seen.append(f["fix"])
        fixes = seen[:5]
    risk_summary = synthesis.get("risk_summary") or (
        f"{len(active)} potential issue(s) flagged by rule-based checks." if active else "No rule-based checks fired."
    )

    files_used = sorted({c.file for c in contracts})
    sources = [{"path": sf.path, "content": sf.content, "lines": sf.line_count} for sf in parsed.files if sf.path in files_used]
    other_files = [sf.path for sf in parsed.files if sf.path not in files_used]

    return {
        "meta": {
            **meta,
            "contract_type": str(synthesis.get("contract_type") or meta["contract_type"])[:80],
            "ai_enabled": provider is not None,
            "ai_provider": getattr(provider, "name", None),
            "ai_model": getattr(provider, "model", None),
            "analyzed_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "files_analyzed": files_used,
            "files_skipped": other_files,
            "line_count": sum(s["lines"] for s in sources),
        },
        "overview": {
            "text": overview_txt,
            "overall_risk": overall,
            "risk_summary": risk_summary,
            "overall_risk_basis": "Highest severity among findings not dismissed as false positives.",
        },
        "contracts": [
            {"name": c.name, "kind": c.kind, "bases": c.bases, "file": c.file, "start_line": c.start_line,
             "end_line": c.end_line, "is_main": c is main, "functions": sum(1 for f in c.functions if f.has_body)}
            for c in contracts
        ],
        "roles": roles_out,
        "key_functions": key_ids,
        "functions": fn_list,
        "findings": findings_out,
        "severity_counts": counts,
        "fixes": fixes,
        "sources": sources,
        "disclaimer": DISCLAIMER,
    }
